#!/usr/bin/env node
// This file is auto-generated by @lark-apaas/fullstack-cli

const { nodeFileTrace } = require('@vercel/nft');
const fs = require('fs');
const path = require('path');

const ROOT_DIR = path.resolve(__dirname, '..');

// 加载提交的 .env，供读取构建期配置（如 MIAODA_RUNTIME_ENTRIES）。dotenv 不一定安装 → 静默降级。
try {
  require('dotenv').config({ path: path.join(ROOT_DIR, '.env') });
} catch {
  // dotenv 未安装：跳过；MIAODA_RUNTIME_ENTRIES 仍可来自真实环境变量
}
const DIST_DIR = path.join(ROOT_DIR, 'dist');
const DIST_SERVER_DIR = path.join(DIST_DIR, 'server');
const ROOT_PACKAGE_JSON = path.join(ROOT_DIR, 'package.json');
const ROOT_NODE_MODULES = path.join(ROOT_DIR, 'node_modules');
const OUT_NODE_MODULES = path.join(DIST_DIR, 'node_modules');
const OUT_PACKAGE_JSON = path.join(DIST_DIR, 'package.json');

// Server 入口文件
const SERVER_ENTRY = path.join(DIST_SERVER_DIR, 'main.js');

// nest sourceRoot（源码根，默认 server）：把 .env 里声明的源码路径映射到构建产物位置
let SOURCE_ROOT = 'server';
try {
  const nestCli = JSON.parse(fs.readFileSync(path.join(ROOT_DIR, 'nest-cli.json'), 'utf8'));
  if (nestCli.sourceRoot) SOURCE_ROOT = nestCli.sourceRoot;
} catch {
  // 读不到 nest-cli.json 则用默认 server
}
const SRC_TO_OUT_EXT = { '.mts': '.mjs', '.cts': '.cjs', '.ts': '.js' };

// 额外 trace 入口：经 new Function/动态 import 加载、nft 无法从 main.js 静态发现的 ESM runtime。
// 应用在提交的 .env 里用 MIAODA_RUNTIME_ENTRIES 声明【源码路径】（相对项目根，逗号分隔），例如：
//   MIAODA_RUNTIME_ENTRIES=server/modules/ethics/runtime/review-run.mjs,server/modules/ethics/runtime/parse-core.mjs
// 脚本按 nest sourceRoot 自动映射到 dist/server 下的构建产物（并重写 .mts→.mjs / .ts→.js）。
const RUNTIME_ENTRIES = (process.env.MIAODA_RUNTIME_ENTRIES || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean)
  .map((srcRel) => {
    const fromSrc = path.relative(SOURCE_ROOT, srcRel); // 去掉 sourceRoot 前缀
    const ext = path.extname(fromSrc);
    const outRel = SRC_TO_OUT_EXT[ext] ? fromSrc.slice(0, -ext.length) + SRC_TO_OUT_EXT[ext] : fromSrc;
    return path.join(DIST_SERVER_DIR, outRel);
  })
  .filter((p) => {
    if (fs.existsSync(p)) return true;
    console.warn(`⚠️  MIAODA_RUNTIME_ENTRIES 入口在构建产物中不存在，已忽略: ${path.relative(ROOT_DIR, p)}`);
    return false;
  });

/**
 * 保留安装层级；嵌套依赖不能扁平替换为根目录同名包。
 */
function isWithin(parent, child) {
  const relative = path.relative(parent, child);
  return relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

function extractPackagePath(filePath) {
  const absolute = path.resolve(ROOT_DIR, filePath);
  if (!isWithin(ROOT_NODE_MODULES, absolute)) return null;
  const parts = path.relative(ROOT_NODE_MODULES, absolute).split(path.sep);
  // NFT 会输出 node_modules 自链接本身；它不是 npm 包。
  if (!parts[0] || parts[0] === 'node_modules' || parts[0].startsWith('.')) return null;
  const start = parts.lastIndexOf('node_modules') + 1;
  const name = parts[start];
  if (!name || name.startsWith('.')) return null;
  const end = start + (name.startsWith('@') ? 2 : 1);
  if (end > parts.length || !parts[end - 1]) return null;
  return path.join(...parts.slice(0, end));
}

function readInstalledPackage(packagePath) {
  const directory = path.join(ROOT_NODE_MODULES, packagePath);
  const installedRoot = fs.realpathSync(ROOT_NODE_MODULES);
  if (fs.realpathSync(directory) !== path.join(installedRoot, packagePath)) {
    throw new Error(`运行依赖包必须位于实际安装层级内，不能借用树外包链接: ${packagePath}`);
  }
  return JSON.parse(fs.readFileSync(path.join(directory, 'package.json'), 'utf8'));
}

/** 按依赖者的 Node 祖先查找顺序解析，只接受本次安装目录内的包。 */
function resolveInstalledPackage(depName, ownerPath, required) {
  const installedRoot = fs.realpathSync(ROOT_NODE_MODULES);
  const boundary = path.dirname(installedRoot);
  let current = ownerPath ? path.join(installedRoot, ownerPath) : boundary;
  while (isWithin(boundary, current)) {
    if (path.basename(current) !== 'node_modules') {
      const candidate = path.join(current, 'node_modules', depName);
      if (isWithin(installedRoot, candidate) && fs.existsSync(path.join(candidate, 'package.json'))) {
        return path.relative(installedRoot, candidate);
      }
    }
    if (current === boundary) break;
    current = path.dirname(current);
  }
  if (required) {
    throw new Error(`缺少必需运行依赖: ${ownerPath || '<root>'} -> ${depName}`);
  }
  return null;
}

/**
 * 递归删除目录
 */
function removeDir(dir) {
  if (fs.existsSync(dir)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

/**
 * 递归复制目录（优化版：优先使用硬链接）
 */
function copyDir(src, dest, stats = { hardLinks: 0, copies: 0 }, ancestors = new Set()) {
  const realSource = fs.realpathSync(src);
  const installedRoot = fs.realpathSync(ROOT_NODE_MODULES);
  if (!isWithin(installedRoot, realSource)) {
    throw new Error(`运行依赖复制来源越出安装目录: ${src} -> ${realSource}`);
  }
  if (ancestors.has(realSource)) throw new Error(`复制目录存在循环链接: ${src}`);
  const parents = new Set([...ancestors, realSource]);
  if (!fs.existsSync(dest)) {
    fs.mkdirSync(dest, { recursive: true });
  }

  const entries = fs.readdirSync(src, { withFileTypes: true });

  for (const entry of entries) {
    // 嵌套包由相同依赖闭包逐包复制，避免整棵复制及重复覆盖。
    if (entry.name === 'node_modules') continue;
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    const sourceStat = entry.isSymbolicLink() ? fs.statSync(srcPath) : entry;
    if (sourceStat.isDirectory()) {
      copyDir(srcPath, destPath, stats, parents);
    } else {
      if (!sourceStat.isFile()) throw new Error(`不能复制运行依赖中的非普通文件: ${srcPath}`);
      // 文件链接解引用，输出不能借用源码树的链接目标。
      const sourceFile = entry.isSymbolicLink()
        ? fs.realpathSync(srcPath)
        : path.join(realSource, entry.name);
      if (!isWithin(installedRoot, sourceFile)) {
        throw new Error(`运行依赖复制来源越出安装目录: ${srcPath} -> ${sourceFile}`);
      }
      try {
        // 优先使用硬链接（CI 环境中安全，速度快，节省空间）
        fs.linkSync(sourceFile, destPath);
        stats.hardLinks++;
      } catch {
        // 硬链接失败时回退到复制（如跨文件系统）
        fs.copyFileSync(sourceFile, destPath);
        stats.copies++;
      }
    }
  }

  return stats;
}

/**
 * 选择性复制包
 */
function copyPackagesSelectively(packages, rootNodeModules, outNodeModules) {
  const copiedCount = { success: 0, failed: 0 };
  const fileStats = { hardLinks: 0, copies: 0 };

  // 确保输出目录存在
  if (fs.existsSync(outNodeModules)) {
    removeDir(outNodeModules);
  }
  fs.mkdirSync(outNodeModules, { recursive: true });

  // 复制每个包
  for (const pkg of packages) {
    const srcPath = path.join(rootNodeModules, pkg);
    const destPath = path.join(outNodeModules, pkg);

    try {
      readInstalledPackage(pkg);
      // 确保父目录存在（处理 scoped packages）
      const destDir = path.dirname(destPath);
      if (!fs.existsSync(destDir)) {
        fs.mkdirSync(destDir, { recursive: true });
      }

      // 复制包目录，收集统计信息
      copyDir(srcPath, destPath, fileStats);
      copiedCount.success++;
    } catch (err) {
      copiedCount.failed++;
      throw new Error(`复制必需运行依赖失败: ${pkg} - ${err.message}`, { cause: err });
    }
  }

  return { copiedCount, fileStats };
}

/**
 * 主函数：智能裁剪
 */
async function smartPrune() {
  console.log('🔍 开始智能依赖分析...\n');

  const totalStartTime = Date.now();

  // 1. 检查入口文件是否存在
  if (!fs.existsSync(SERVER_ENTRY)) {
    console.error(`❌ 入口文件不存在: ${SERVER_ENTRY}`);
    console.error('   请先运行 npm run build:server');
    process.exit(1);
  }

  console.log(`📂 分析入口文件: ${path.relative(ROOT_DIR, SERVER_ENTRY)}`);
  if (RUNTIME_ENTRIES.length) {
    console.log(`📎 额外 trace 入口 (${RUNTIME_ENTRIES.length}): ${RUNTIME_ENTRIES.map((p) => path.relative(DIST_SERVER_DIR, p)).join(', ')}`);
  }

  // 2. 使用 @vercel/nft 追踪依赖
  if (!isWithin(fs.realpathSync(ROOT_DIR), fs.realpathSync(ROOT_NODE_MODULES))) {
    throw new Error('node_modules 实际路径在 NFT base 之外，无法生成完整依赖包；请使用树内已有依赖副本');
  }
  console.log('🔎 追踪实际依赖...');
  const analyzeStart = Date.now();

  const { fileList } = await nodeFileTrace([SERVER_ENTRY, ...RUNTIME_ENTRIES], {
    base: ROOT_DIR,
    processCwd: ROOT_DIR,
    ts: false, // 禁用 TS 解析
    conditions: ['node', 'production'], // 只解析 Node.js 生产环境的导出
    exportsOnly: true, // 只使用 package.json 的 exports 字段
    analysis: {
      emitGlobs: false, // 禁用 glob 分析
      computeFileReferences: false, // 禁用文件引用计算
      evaluatePureExpressions: false, // 禁用纯表达式求值
    },
  });

  const analyzeElapsed = Date.now() - analyzeStart;
  console.log(`   ✅ 分析完成，耗时: ${analyzeElapsed}ms\n`);

  // 3. 提取 npm 包的实际安装路径
  const requiredPackages = new Set();

  for (const file of fileList) {
    // 快速跳过非 node_modules 文件
    if (!file.includes('node_modules')) continue;

    const packagePath = extractPackagePath(file);
    if (packagePath) requiredPackages.add(packagePath);
  }

  console.log(`📦 静态分析需要 ${requiredPackages.size} 个 npm 包`);

  // 4. 从 nft 结果递归收集子依赖（处理动态 require 无法被静态分析追踪的问题）
  // 某些包（如 pdf-parse）使用 try-catch 动态加载依赖（如 @napi-rs/canvas），
  // @vercel/nft 无法追踪这类依赖，需要基于 package.json 声明补充
  // 策略：只对 nft 已追踪到的包递归，避免收集无关依赖
  const originalPackage = JSON.parse(fs.readFileSync(ROOT_PACKAGE_JSON, 'utf8'));

  // 插件是实际运行根，必须与静态根一起补全依赖及必需 peer。
  const actionPlugins = originalPackage.actionPlugins || {};
  const actionPluginNames = Object.keys(actionPlugins);
  for (const pluginName of actionPluginNames) {
    requiredPackages.add(resolveInstalledPackage(pluginName, null, true));
  }

  let addedSubDeps = 0;
  const visited = new Set(); // 防止循环依赖导致无限循环
  const queue = [...requiredPackages]; // BFS 队列，从 nft 结果开始（更精准）

  while (queue.length > 0) {
    const depName = queue.shift();

    // 跳过已访问的包（防止循环依赖）
    if (visited.has(depName)) continue;
    visited.add(depName);

    const depPkg = readInstalledPackage(depName);
    const optionalDeps = depPkg.optionalDependencies || {};
    const requiredDeps = { ...depPkg.dependencies };
    // npm optionalDependencies 覆盖同名 dependencies。
    for (const optional of Object.keys(optionalDeps)) delete requiredDeps[optional];
    for (const peer of Object.keys(depPkg.peerDependencies || {})) {
      if (!depPkg.peerDependenciesMeta?.[peer]?.optional) requiredDeps[peer] = depPkg.peerDependencies[peer];
    }
    const subDeps = new Set([...Object.keys(requiredDeps), ...Object.keys(optionalDeps)]);
    for (const subDep of subDeps) {
      const packagePath = resolveInstalledPackage(subDep, depName, Object.hasOwn(requiredDeps, subDep));
      if (!packagePath) continue; // 未安装的声明 optional 依赖允许缺省。
      if (!requiredPackages.has(packagePath)) {
        requiredPackages.add(packagePath);
        addedSubDeps++;
      }
      if (!visited.has(packagePath)) queue.push(packagePath);
    }
  }

  if (addedSubDeps > 0) {
    console.log(`📦 递归补充动态依赖，新增 ${addedSubDeps} 个包`);
  }

  // 5. 插件已随运行闭包解析，保留插件声明及输出。
  if (actionPluginNames.length > 0) {
    console.log(`   ✅ 插件: ${actionPluginNames.join(', ')}`);
  }

  console.log(`📦 总共需要 ${requiredPackages.size} 个 npm 包\n`);

  // 6. 选择性复制包（只复制需要的）
  console.log('📋 选择性复制 node_modules（仅复制需要的包）...');
  const copyStart = Date.now();

  const sortedPackages = Array.from(requiredPackages).sort();
  const { copiedCount, fileStats } = copyPackagesSelectively(sortedPackages, ROOT_NODE_MODULES, OUT_NODE_MODULES);

  const copyElapsed = Date.now() - copyStart;
  console.log(`   ✅ 复制完成，耗时: ${copyElapsed}ms`);
  console.log(`   成功: ${copiedCount.success} 个包，失败: ${copiedCount.failed} 个`);
  console.log(`   硬链接: ${fileStats.hardLinks} 个文件，复制: ${fileStats.copies} 个文件\n`);

  // 7. 生成精简版 package.json
  // 优化：直接构建 dependencies，避免多次对象展开
  const prunedDependencies = {};
  const allDeps = originalPackage.dependencies || {};
  const allDevDeps = originalPackage.devDependencies || {};

  for (const pkg of requiredPackages) {
    // 优先从 dependencies/devDependencies 获取版本，其次从 actionPlugins 获取
    const version = allDeps[pkg] || allDevDeps[pkg] || actionPlugins[pkg];
    if (version) {
      prunedDependencies[pkg] = version;
    }
  }

  const prunedPackage = {
    name: originalPackage.name,
    version: originalPackage.version,
    private: true,
    dependencies: prunedDependencies,
    engines: originalPackage.engines
  };

  fs.writeFileSync(OUT_PACKAGE_JSON, JSON.stringify(prunedPackage, null, 2));

  const totalElapsed = Date.now() - totalStartTime;

  // 8. 输出统计信息
  console.log('='.repeat(60));
  console.log('📊 智能裁剪统计:');
  console.log('='.repeat(60));
  console.log(`  需要的包数量:   ${requiredPackages.size}`);
  if (actionPluginNames.length > 0) {
    console.log(`  Action 插件:    ${actionPluginNames.length} 个`);
  }
  console.log(`  成功复制:       ${copiedCount.success} 个包`);
  console.log(`  失败:           ${copiedCount.failed} 个包`);
  console.log(`  硬链接文件:     ${fileStats.hardLinks} 个`);
  console.log(`  复制文件:       ${fileStats.copies} 个`);
  console.log(`  分析耗时:       ${analyzeElapsed}ms`);
  console.log(`  复制耗时:       ${copyElapsed}ms`);
  console.log(`  总耗时:         ${totalElapsed}ms`);
  console.log('='.repeat(60) + '\n');

  console.log('✅ 智能裁剪完成！');
  console.log(`📍 精简的 package.json 已保存到: ${OUT_PACKAGE_JSON}\n`);
}

// 运行智能裁剪
smartPrune().catch(err => {
  console.error('❌ 智能裁剪失败:', err);
  process.exit(1);
});
